// Date Preprocessor v6.0 - Enhanced with Argentina timezone + Masajista data passthrough
// Calculates current date/time PLUS next 7 days
// Properly handles GMT-3 (America/Argentina/Buenos_Aires)
// Passes through masajista data from upstream

// Get UTC time
const utcNow = new Date();

// Convert to Argentina time (GMT-3)
// Method: Get UTC components, then adjust to Argentina
const argOffset = -3 * 60; // Argentina is UTC-3 (180 minutes behind UTC)
const argTime = new Date(utcNow.getTime() + argOffset * 60 * 1000);

// Use Argentina time for all calculations
const now = argTime;

// Spanish day names (without accents as per system requirements)
const dayNames = ['Domingo', 'Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'];
const monthNames = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
                   'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];

// Calculate next 7 days (including today) - ALL in Argentina time
const next7Days = [];
for (let i = 0; i < 7; i++) {
  const date = new Date(now);
  date.setDate(date.getDate() + i);

  const dayName = dayNames[date.getDay()];
  const dayNumber = date.getDate();
  const monthName = monthNames[date.getMonth()];
  const year = date.getFullYear();

  // ISO format YYYY-MM-DD (using Argentina date)
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const dateISO = `${y}-${m}-${d}`;

  next7Days.push({
    offset: i,
    dayName: dayName,
    dayNumber: dayNumber,
    monthName: monthName,
    year: year,
    dateReadable: `${dayNumber} de ${monthName} de ${year}`,
    dateISO: dateISO,
    // Helper field for natural language
    label: i === 0 ? 'hoy' : i === 1 ? 'mañana' : i === 2 ? 'pasado mañana' : dayName
  });
}

// Current time info (Argentina time)
const currentHour = String(now.getHours()).padStart(2, '0');
const currentMinute = String(now.getMinutes()).padStart(2, '0');

// Pass through all original data + preprocessed date fields + masajista data
return {
  ...items[0].json,

  // Current date/time (Argentina)
  current_day: next7Days[0].dayName,
  current_date: next7Days[0].dayNumber,
  current_month: next7Days[0].monthName,
  current_year: next7Days[0].year,
  current_date_readable: next7Days[0].dateReadable,
  current_date_iso: next7Days[0].dateISO,
  current_time: `${currentHour}:${currentMinute}`,
  current_hour: parseInt(currentHour),
  current_minute: parseInt(currentMinute),

  // Tomorrow (Argentina)
  tomorrow_day: next7Days[1].dayName,
  tomorrow_date: next7Days[1].dayNumber,
  tomorrow_month: next7Days[1].monthName,
  tomorrow_year: next7Days[1].year,
  tomorrow_date_readable: next7Days[1].dateReadable,
  tomorrow_date_iso: next7Days[1].dateISO,

  // 7-day array for lookups (all Argentina time)
  next_7_days: next7Days,

  // Helper: Create a quick lookup message for the AI
  days_summary: `Hoy es ${next7Days[0].dayName}. Los próximos días: ${next7Days.slice(1, 7).map((d, i) => `${d.label}`).join(', ')}.`,

  // Timestamps for debugging/reference
  original_now_utc: utcNow.toISOString(),  // Original UTC time
  original_now_argentina: now.toISOString(), // Argentina time (for verification)
  timezone_info: "America/Argentina/Buenos_Aires (GMT-3)"
};

const output = $input.first().json.output;

  // Find JSON object anywhere in the string
const jsonMatch = output.match(/\{[\s\S]*\}/);

  if (!jsonMatch) {
    return {
