      paciente_id: parsed.paciente_id || null,
      medico_id: parsed.medico_id || null,
      dni: parsed.dni || null
    };
  } catch (e) {
    return {
      tipo: 'consulta',
      mensaje: output,
      contexto: null,
      search_key_type: null,
      key_type_value: null
    };
  }

const message = $('Telegram Trigger').first().json.message.text

  let command = null;

 if (message === '#on') {
   command = 'on';
 } else if (message === '#off') {
   command = 'off';
 } else if (message === '#info') {
   command = 'info';
 } else if (message.startsWith('#blacklist')) {
   command = 'blacklist';
 } else if (message.startsWith('#unblacklist')) {
 command = 'unblacklist';
 }

 return {
   ...$input.first().json,
   command: command
 };

// Get the phone number from the Telegram message (after "#blacklist ")
  const message = $('Telegram Trigger').first().json.message.text;
  const phoneNumber = message.split(' ')[1] || '';

  // Get blacklist entries from the previous DataTable node
  const blacklistEntries = $input.all();

  // Check if phoneNumber exists in blacklist
  // Handle empty results: empty array OR array with empty object
  const isAlreadyBlacklisted = blacklistEntries.some(entry =>
    entry.json &&
    entry.json.telefono &&
    entry.json.telefono === phoneNumber
  );

  if (!phoneNumber) {
    return {
      status: 'invalid',
      phoneNumber: '',
      message: 'No se proporcionó un número de teléfono'
    };
  }

  if (isAlreadyBlacklisted) {
    return {
      status: 'already_blacklisted',
      phoneNumber: phoneNumber,
      message: `El número ${phoneNumber} ya se encuentra anulado`
    };
  } else {
    return {
      status: 'not_blacklisted',
      phoneNumber: phoneNumber
    };
  }

