// Get all pending messages from previous node
  const pendingMessages = $input.all();

  // If no messages found, another execution already claimed them - exit
  if (!pendingMessages || pendingMessages.length === 0) {
    return [];
  }

  // Extract message data
  const messages = pendingMessages.map(item => ({
    id: item.json.id,
    telefono: item.json.telefono,
    mensaje: item.json.mensaje,
    timestamp: item.json.timestamp,
    tipo: item.json.tipo
  }));

  // Sort by timestamp
  messages.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

  // Check if any message is audio
  const has_audio = messages.some(m => ['audio', 'audioMessage'].includes(m.tipo));

  // Shared data
  const telefono = messages[0].telefono;
  const mensaje_concatenado = messages.map(m => m.mensaje).join(' | ');
  const mensaje_count = messages.length;
  const all_ids = messages.map(m => m.id);

  // Return one item per ID - no Split Out needed
  return messages.map(m => ({
    json: {
      telefono,
      mensaje_concatenado,
      mensaje_count,
      all_ids,
      has_audio,
      id_to_update: m.id
    }
  }));

// Get all_ids from Date_preprocessor (where it was passed through)
  const allIds = $input.first().json.all_ids;

  // Handle case where all_ids might be a string (from Restaurar contexto)
  let idsArray;
  if (typeof allIds === 'string') {
    // Parse if it's a string like "[6,7]"
    idsArray = JSON.parse(allIds);
  } else if (Array.isArray(allIds)) {
    idsArray = allIds;
  } else {
    // No IDs to update
    return [];
  }

  // Return one item per ID
  return idsArray.map(id => ({
    json: {
      id_to_complete: id
    }
  }));

const tokenData = $input.first().json;
